$(function() {
    $('#timer').timer({
        action:'start',
        seconds: 0
    });

    setInterval(function() {
        updateSessionByInterval();
    }, 60000); //2.5 Minutes = 150000

    setInterval(function() {
        checkTempTime();
    }, 150000); //2.5 Minutes = 150000

    setTimeout(roomReload, 100);

    $(document).on("click", "#extend-temp-session", function (e) {
        e.preventDefault(); // avoid to execute the actual submit of the form.
        var tempid = parseInt($('#tempid').val());
        sessionModal('hide');
        if(tempid > 0) {
            var obj = $(this);
            var url = obj.attr('href') + '/' + tempid;
            $.ajax({
                type: "GET",
                url: url,
                data: {}, // serializes the form's elements.
                dataType: 'JSON',
                success: function (result) {
                    alert(result.message);
                    if (result.status == '1') {
                        sessionModal('hide');
                    } else {
                        reload();
                    }
                },
                error: function (data) {
                    console.log('An error occurred.');
                    console.log(data);
                }
            });
        } else {
            sessionModal('hide');
        }
    });


    $(document).on("click", "#destroy-temp-session", function (e) {
        e.preventDefault(); // avoid to execute the actual submit of the form.
        var tempid = parseInt($('#tempid').val());
        sessionModal('hide');
        if(tempid > 0) {
            var obj = $(this);
            var url = obj.attr('href') + '/' + tempid;
            //alert(url);
            $.ajax({
                type: "GET",
                url: url,
                data: {}, // serializes the form's elements.
                dataType: 'JSON',
                success: function (result) {
                    alert(result.message);
                    reload();
                },
                error: function (data) {
                    console.log('An error occurred.');
                    console.log(data);
                }
            });
        } else {
            sessionModal('hide');
        }
    });


    $(document).on("click", "#removesession", function (e) {
        e.preventDefault(); // avoid to execute the actual submit of the form.
        var tempid = parseInt($('#tempid').val());
        if(tempid > 0) {
            var obj = $(this);
            var url = obj.attr('href') + '/' + tempid;
            //alert(url);
            $.ajax({
                type: "GET",
                url: url,
                data: {}, // serializes the form's elements.
                dataType: 'JSON',
                success: function (result) {
                    alert(result.message);
                    reload();
                },
                error: function (data) {
                    console.log('An error occurred.');
                    console.log(data);
                }
            });
        } else {
            alert('SESSION NOT FOUND TO DESTROY');
        }
    });


    //ROOM WORK///////////////////
    $(document).on("click", ".room-status-deactivate", function (e) {
        e.preventDefault(); // avoid to execute the actual submit of the form.
        var obj = $(this);
        var container = obj.closest('.room-status-current');
        var roomno = container.attr('data-value');
        $.ajax({
            type: "GET",
            url: obj.attr('href'),
            data: {'roomno':roomno},
            dataType: 'JSON',
            global:false,
            success: function (result) {
                if (result.status == '1') {
                    container.html('<a class="room-status-activate text-danger" href="/room/setting/room/activate" title="CURRENT STATUS: INACTIVE<br>CLICK TO ACTIVATE"><i class="fas fa-times-circle fa-2x"></i></a>');
                } else {
                    alert(result.message);
                }
            },
            error: function (data) {
                console.log('An error occurred.');
                console.log(data);
            }
        });
    });


    $(document).on("click", ".room-status-activate", function (e) {
        e.preventDefault(); // avoid to execute the actual submit of the form.
        var obj = $(this);
        var container = obj.closest('.room-status-current');
        var roomno = container.attr('data-value');
        $.ajax({
            type: "GET",
            url: obj.attr('href'),
            data: {'roomno':roomno},
            dataType: 'JSON',
            global:false,
            success: function (result) {
                if (result.status == '1') {
                    container.html('<a class="room-status-deactivate text-success" href="/room/setting/room/deactivate" title="CURRENT STATUS: ACTIVE<br>CLICK TO MAKE INACTIVE"><i class="fas fa-check-circle fa-2x"></i></a>');
                } else {
                    alert(result.message);
                }
            },
            error: function (data) {
                console.log('An error occurred.');
                console.log(data);
            }
        });
    });

    $(document).on("submit", "form#room-load-to-grid", function (e) {
        e.preventDefault(); // avoid to execute the actual submit of the form.
        var form = $(this);
        var url = form.attr('action');
        var panel = form.closest('.panel');
        var tempid = $('#tempid').val();
        var fullday = [];
        if($('input.check-fullday:checkbox:checked').length > 0) {
            $("input.check-fullday:checkbox:checked").each(function (i) {
                fullday[i] = $(this).val();
            });
           // alert(fullday.join())
        }
        $('#reservationgrid').html('');
        var discountby = 'NODISCOUNT';
        var discountloaded = false;
        if(isset($('#room-discount-by'))) {
            discountby = $('#room-discount-by').val();
            discountloaded = true;
        }
        $.ajax({
            type: "POST",
            url: url,
            data: form.serialize()+'&check_fullday='+fullday.join(), // serializes the form's elements.
            dataType:'JSON',
            success: function(result)
            {
                $('#roomgrid-panel').html(result.content);
                $('#room-action-panel').html(result.action).show();
                $('#masterroom').html(result.masterroom).val($('#masterroom').attr('data-value')).trigger('chosen:updated');
                if(isset($('#room-discount-by'))) {
                    if(!discountloaded){
                        $('#room-discount-by').val($('#room-discount-by').attr('data-value')).trigger('change');
                    } else {
                        $('#room-discount-by').val(discountby).trigger('change');
                    }
                }
                if(result.status == '1') {
                    var roomtable = $('#roomgrid-panel').find('#roomgrid');
                    roomtable.find('td.active-room').each(function (i) {
                        var td = $(this);
                        var tdaction = td.data('action');
                        if (tdaction == 'hold-room-xb') {
                            $(this).html('<a class="btn btn-success room-action" data-action="hold-room" title="HOLD ROOM<br>RATE: TK ' + bdt_format(td.data('rate')) + '"><i class="fas fa-bed fa-lg text-light"></i></a> <a class="btn btn-success room-action" data-action="hold-xb"title="HOLD EXTRA BED<br>RATE: TK ' + bdt_format(td.data('xb-rate')) + '"><i class="fas fa-plus-square fa-lg text-light"></i></a>');
                        } else if (tdaction == 'release-room' || tdaction == 'hold-xb') {
                            var tdtempid = td.data('tempid');
                            if (tempid == tdtempid) {
                                switch (tdaction) {
                                    case 'release-room':
                                        $(this).html('<a class="btn btn-warning room-action" data-action="release-room" title="RELEASE ROOM"><i class="fas fa-bed fa-lg text-light"></i></a> <a class="btn btn-warning room-action" data-action="release-xb" title="RELEASE EXTRA BED"><i class="fas fa-plus-square fa-lg text-light"></i></a>');
                                        break;
                                    case 'hold-xb':
                                        $(this).html('<a class="btn btn-warning room-action" data-action="release-room" title="RELEASE ROOM"><i class="fas fa-bed fa-lg text-light"></i></a> <a class="btn btn-success room-action" data-action="hold-xb" title="HOLD EXTRA BED<br>RATE: TK ' + bdt_format(td.data('xb-rate')) + '"><i class="fas fa-plus-square fa-lg text-light"></i></a>');
                                        break;
                                }
                            } else {
                                td.addClass('bg-warning').attr('title', 'HOLD BY ' + td.data('user') + ' FROM ' + td.data('from'));
                            }
                        }
                    });
                    var table = roomtable.DataTable({
                        scrollY: window.screen.height - 220 + "px",
                        scrollX: true,
                        scrollCollapse: true,
                        paging: false,
                        searching: false,
                        ordering: false,
                        info: false,
                        fixedColumns: {
                            leftColumns: 2
                        }
                    });

                    $('#room-search-control').click();
                }

            },
            error: function (data) {
                console.log('An error occurred.');
                console.log(data);
            }
        });
    });

    $(document).on("submit", "form#load-reservation", function (e) {
        e.preventDefault(); // avoid to execute the actual submit of the form.
        var form = $(this);
        var url = form.attr('action');
        var redirectto = form.data('redirect-to');
        $.ajax({
            type: "POST",
            url: url,
            data: form.serialize(), // serializes the form's elements.
            dataType:'JSON',
            success: function(result)
            {
                if(result.status == '1'){
                    redirect(redirectto+'/'+result.reservationid);
                }
            },
            error: function (data) {
                console.log('An error occurred.');
                console.log(data);
            }
        });
    });


    /**
     * Reservation List
     */

    $('#fixeddatatable-left-right').DataTable( {
        scrollY:        window.screen.height-350+"px",
        scrollX:        true,
        scrollCollapse: true,
        paging:         false,
        info: false,
        fixedColumns:   {
            leftColumns: 1,
            rightColumns: 2
        }
    });

})


function roomReload(){
    if($('form.room-load-to-grid').length > 0){
        $('form.room-load-to-grid').trigger('submit');
    }
    if($('#room-sales-next-tab').length > 0){
        $('#room-sales-next-tab').trigger('click');
    }
}
